import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import '../../blocs/portal_bloc.dart';
import '../../enums/enums.dart';
import '../../models/models.dart';
import '../../repositories/mock_repository.dart';
import '../widgets/shared_widgets.dart';
import 'student_portal.dart';
import 'portals.dart';

class SchoolAutomateApp extends StatelessWidget { const SchoolAutomateApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(title:'School Automate',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,scaffoldBackgroundColor:surface,colorScheme:ColorScheme.fromSeed(seedColor:blue,brightness:Brightness.light),fontFamily:'Arial',inputDecorationTheme:const InputDecorationTheme(border:OutlineInputBorder(),filled:true,fillColor:Colors.white)),home:const RoleShell()); }
class RoleShell extends StatefulWidget { const RoleShell({super.key}); @override State<RoleShell> createState()=>_RoleShellState(); }
class _RoleShellState extends State<RoleShell> { UserRole role=UserRole.student; final repo=MockRepository(); @override Widget build(BuildContext context){ return Scaffold(body:role==UserRole.student?BlocProvider(create:(_)=>StudentBloc(repo),child:StudentPortal(onRoleChanged:(r)=>setState(()=>role=r))):role==UserRole.teacher?BlocProvider(create:(_)=>TeacherBloc(repo),child:TeacherPortal(onRoleChanged:(r)=>setState(()=>role=r))):BlocProvider(create:(_)=>RegistrarBloc(repo),child:RegistrarPortal(onRoleChanged:(r)=>setState(()=>role=r))); } }

class PortalHeader extends StatelessWidget { final String eyebrow,title,subtitle; final UserRole role; final ValueChanged<UserRole> onRoleChanged; const PortalHeader({required this.eyebrow,required this.title,required this.subtitle,required this.role,required this.onRoleChanged,super.key}); @override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.fromLTRB(28,22,28,20),decoration:const BoxDecoration(color:Colors.white,border:Border(bottom:BorderSide(color:Color(0xFFE8ECF4)))),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(eyebrow,style:const TextStyle(color:muted,fontSize:12,fontWeight:FontWeight.w600)),const SizedBox(height:5),Text(title,style:const TextStyle(color:ink,fontSize:26,fontWeight:FontWeight.w800)),const SizedBox(height:4),Text(subtitle,style:const TextStyle(color:muted))])),DropdownButton<UserRole>(value:role,underline:const SizedBox(),borderRadius:BorderRadius.circular(14),items:UserRole.values.where((r)=>r==UserRole.student||r==UserRole.teacher||r==UserRole.registrar).map((r)=>DropdownMenuItem(value:r,child:Text(r.label))).toList(),onChanged:(value){if(value!=null) onRoleChanged(value);})])); }
class SideNav extends StatelessWidget { final String label; final List<String> items; final int selected; final ValueChanged<int> onTap; const SideNav({required this.label,required this.items,required this.selected,required this.onTap,super.key}); @override Widget build(BuildContext context)=>Container(width:240,color:navy,padding:const EdgeInsets.fromLTRB(18,24,18,18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('SCHOOL',style:TextStyle(color:Color(0xFF8EA0C8),fontSize:11,fontWeight:FontWeight.w700,letterSpacing:1.5)),const SizedBox(height:8),const Text('AUTOMATE',style:TextStyle(color:Colors.white,fontSize:23,fontWeight:FontWeight.w900,letterSpacing:1)),const SizedBox(height:48),Text(label.toUpperCase(),style:const TextStyle(color:Color(0xFF8EA0C8),fontSize:10,fontWeight:FontWeight.w700,letterSpacing:1)),const SizedBox(height:12),...items.asMap().entries.map((item)=>Container(margin:const EdgeInsets.only(bottom:6),decoration:BoxDecoration(color:item.key==selected?const Color(0xFF24365E):Colors.transparent,borderRadius:BorderRadius.circular(10)),child:ListTile(dense:true,leading:Icon([Icons.grid_view,Icons.edit_note,Icons.menu_book,Icons.people_alt][item.key%4],color:item.key==selected?Colors.white:const Color(0xFFAEBBD7),size:20),title:Text(item.value,style:TextStyle(color:item.key==selected?Colors.white:const Color(0xFFAEBBD7),fontWeight:item.key==selected?FontWeight.w700:FontWeight.w500)),onTap:()=>onTap(item.key))),const Spacer(),const Divider(color:Color(0xFF2E416A)),const ListTile(leading:Icon(Icons.logout,color:Color(0xFFAEBBD7)),title:Text('Sign out',style:TextStyle(color:Color(0xFFAEBBD7))))])); }
